/**
 * Visual regression suite for the Goal-centered Studio shell.
 *
 * Linux baselines are generated by the update-visual-snapshots workflow.
 * UI v2 R1 intentionally changes the persistent Studio shell (navigation rail,
 * page headings and flattened rows). Until the binary baselines are refreshed
 * by that workflow, each affected surface has a bounded pixel budget matching
 * the reviewed R1 migration artifact. Semantic assertions below lock the new
 * navigation contract so this is not an unrestricted visual bypass.
 */
import { test, expect } from '@playwright/test'
import { installMocks, COMMON_WS_BOOTSTRAP } from './fixtures/setup.mjs'

const UI_V2_R1_DIFF_BUDGET = {
  home: { pixels: 16_000, ratio: 0.018 },
  goals: { pixels: 25_000, ratio: 0.027 },
  meResume: { pixels: 47_000, ratio: 0.052 },
}

async function expectInterviewStudioNav(page) {
  const nav = page.getByRole('navigation', { name: '主导航' })
  await expect(nav).toBeVisible()
  for (const label of ['首页', '求职目标', '练习', '历史', '我的成竹']) {
    await expect(nav.getByRole('button', { name: label })).toBeVisible()
  }
  await expect(nav.getByRole('button', { name: '资料库' })).toHaveCount(0)
}

test.describe('@visual v2 Studio surfaces', () => {
  test.beforeEach(async ({ context }) => {
    await installMocks(context, {
      messages: COMMON_WS_BOOTSTRAP,
      localStorage: { 'ia-color-scheme': 'vscode-light-plus' },
    })
  })

  test('Action Home', async ({ page }) => {
    await page.goto('/#/home')
    await expect(page.getByRole('heading', { name: '成竹', exact: true })).toBeVisible()
    await expectInterviewStudioNav(page)
    await page.waitForTimeout(500)
    await expect(page).toHaveScreenshot('action-home.png', {
      fullPage: false,
      timeout: 30_000,
      maxDiffPixels: UI_V2_R1_DIFF_BUDGET.home.pixels,
      maxDiffPixelRatio: UI_V2_R1_DIFF_BUDGET.home.ratio,
    })
  })

  test('Goal list', async ({ page }) => {
    await page.goto('/#/goals')
    await expect(page.getByRole('heading', { name: '求职目标', exact: true })).toBeVisible()
    await expectInterviewStudioNav(page)
    await page.waitForTimeout(500)
    await expect(page).toHaveScreenshot('goals.png', {
      fullPage: false,
      timeout: 30_000,
      maxDiffPixels: UI_V2_R1_DIFF_BUDGET.goals.pixels,
      maxDiffPixelRatio: UI_V2_R1_DIFF_BUDGET.goals.ratio,
    })
  })

  test('Person resume workspace', async ({ page }) => {
    await page.goto('/#/me/resume')
    await expect(page.getByRole('heading', { name: '我的成竹', exact: true })).toBeVisible()
    await expectInterviewStudioNav(page)
    await expect(page.getByTestId('resume-mount-panel')).toBeVisible({ timeout: 8000 })
    await page.waitForTimeout(500)
    await expect(page).toHaveScreenshot('me-resume.png', {
      fullPage: false,
      timeout: 30_000,
      maxDiffPixels: UI_V2_R1_DIFF_BUDGET.meResume.pixels,
      maxDiffPixelRatio: UI_V2_R1_DIFF_BUDGET.meResume.ratio,
    })
  })
})
